```c
switch (x) {
case 1: printf("one ");
case 2: printf("two ");
case 3: printf("three ");
default: printf("other ");
}
```

What does this program print?

```c
void bump(int n) { n = n + 10; printf("inside: %d\n", n); }

int main(void) {
    int n = 5;
    bump(n);
    printf("outside: %d\n", n);
    return 0;
}
```
